INSERT INTO "books" VALUES(52,'A Dog''s Purpose - A Novel For Humans','W. Bruce Cameron','The soulful and surprising story of one devoted dog (voiced by Josh Gad) who finds the meaning of his own existence through the lives of the humans he teaches to laugh and love.','Animal Fiction','','','','9780765388100','',1,0,NULL,NULL,NULL,NULL);
INSERT INTO "books" VALUES(53,'Kingdoms of Elfin (Anthology)','Sylvia Townsend Warner','Changelings and poets, dissidents and gypsies, professors an witches, as well as fairies of high and low degree, spring to life in these magical tales.','Fantasy','','','','','',1,0,NULL,NULL,NULL,NULL);
INSERT INTO "books" VALUES(54,'Three Kings - Edited By George R. R. Martin','George R.R. Martin','The return of the famous shared-world superhero books created and edited by George R. R. Martin, author of A Song of Ice and Fire.','Fantasy','','','','9780008361525','',1,0,NULL,NULL,NULL,NULL);
INSERT INTO "books" VALUES(55,'Fables de La Fontaine','Jean de La Fontaine','244 fables, illustrated with over 250 illustrations (French language))','Classic','','','','','',1,0,NULL,NULL,NULL,NULL);
