INSERT INTO "books" VALUES(201,'Comme une bête','Joy Sorman','Comme une bête est l''histoire d''un jeune homme qui aime les vaches au point de devenir boucher.','Animal Fiction','','','','9782070456161','',1,0,'0',0,NULL,NULL);
INSERT INTO "books" VALUES(202,'How Death Becomes Life - Notes From A Transplant Surgeon','Joshua Mezrich','A beautifully written and compelling memoir of a largely unexplored area of medicine: transplant surgery. Leading transplant surgeon Dr Joshua Mezrich creates life from loss, moving organs from one body to another. In this intimate, profoundly moving work, he examines more than one hundred years of remarkable medical breakthroughs, connecting this fascinating history with the stories of his own patients. Gripping and evocative, How Death Becomes Life takes us inside the operating room and presents the stark dilemmas that transplant surgeons must face daily: How much risk should a healthy person be allowed to take to save someone she loves? Should a patient suffering from alcoholism receive a healthy liver? The human story behind the most exceptional medicine of our time, Mezrich''s riveting book is a poignant reminder that a life lost can also offer the hope of a new beginning.','Reference','','','','9781786498892','',1,0,'0',0,NULL,NULL);
INSERT INTO "books" VALUES(203,'Larousse Pocket Diccionario Español-inglés, Inglés-español','Larousse','Provides Spanish and English equivalents for more than eighty thousand expressions','Reference','','','','9782034208003','',1,0,'0',0,NULL,NULL);
