INSERT INTO "books" VALUES(425,'Seventeen Equations That Changed the World (VN language)','Ian Stewart','Famous mathematical equations are described and discussed in a language that allows non-mathematician to understand and appreciate their importance in modern world. Entertaining, and educational. Vietnamese translation by Pham Van Thieu and Nguyen Duy Khanh. In Vietnamese. Annotation copyright Tsai Fong Books, Inc. Distributed by Tsai Fong Books, Inc.','Reference','','','','9786041069480','',1,0,'0',0,NULL,NULL);
