INSERT INTO "books" VALUES(427,'Simon And Schuster''s Guide To Mammals','Luigi Boitani','Mammals includes 426 world species. An introduction to evolution, characteristics, and orders of mammals classification, description, and habitat as well as details on behavior, feeding habits, and reproduction. also color Synbols to illustrate habitat, color maps to show the rarity of each species.','Reference','','','','9780671244170','',1,0,'0',0,NULL,NULL);
INSERT INTO "books" VALUES(428,'Sprint - How To Solve Big Problems And Test New Ideas In Just Five Days','Jake Knapp','“Sprint offers a transformative formula for testing ideas that works whether you’re at a startup or a large organization. Within five days, you’ll move from idea to prototype to decision, saving you and your team countless hours and countless dollars. A must read for entrepreneurs of all stripes.” —Eric Ries, author of The Lean Startup From three partners at Google Ventures, a unique five-day process for solving tough problems, proven at more than a hundred companies. Entrepreneurs and leaders face big questions every day: What’s the most important place to focus your effort, and how do you start? What will your idea look like in real life? How many meetings and discussions does it take before you can be sure you have the right solution? Now there’s a surefire way to answer these important questions: the sprint. Designer Jake Knapp created the five-day process at Google, where sprints were used on everything from Google Search to Google X. He joined Braden Kowitz and John Zeratsky at Google Ventures, and together they have completed more than a hundred sprints with companies in mobile, e-commerce, healthcare, finance, and more. A practical guide to answering critical business questions, Sprint is a book for teams of any size, from small startups to Fortune 100s, from teachers to nonprofits. It’s for anyone with a big opportunity, problem, or idea who needs to get answers today.','Reference','','','','9781501140808','',1,0,'0',0,NULL,NULL);
INSERT INTO "books" VALUES(429,'Anne Of Green Gables','L.M. Montgomery','This classic story follows Anne, a spirited orphan, as she uses her imagination and love of reading to become the heart of her new community.','Classic','','','','9781631062476','',1,0,'0',0,NULL,NULL);
INSERT INTO "books" VALUES(430,'Anne Of Avonlea','L. M. Montgomery','Complete and unabridged editions of the world''s most popular and enduring titles. Highly collectable with quality hardback and modern covers, this is an attractive series of classic literature. AGES: 8 + z','Classic','','','','9781782701002','',1,0,'0',0,NULL,NULL);
