INSERT INTO "books" VALUES(433,'Wave Me Goodbye','Jacqueline Wilson','September, 1939: At the breakout of the Second World War, ten-year-old Shirley is sent away on a train. She doesn''t know where she''s going, or what''s going to happen to her when she gets there. All she has been told is that she''s going on ''a little holiday''. She soon finds herself lodged deep in the countryside, with two boys from the East End of London, Kevin and Archie. But here, living in the strange, half-empty Red House with the mysterious and reclusive Mrs Waverley, the children''s lives will be changed for ever. Award-winning, bestselling and beloved author Jacqueline Wilson pens an unforgettable story about the confusion and loneliness of a World War II evacuee, with a moving and hopeful friendship at its centre. ''A heart-warming story packed with Second World War detail'' - Daily Express ''Carrie''s War for a new generation of children'' - Belfast Telagraph','Young Adult','','','','9780440871514','',1,0,'0',0,NULL,NULL);
INSERT INTO "books" VALUES(434,'The Jungle Book','Rudyard Kipling','Unabridged classic ','Classic','','','','9780723544845','',1,0,'0',0,NULL,NULL);
INSERT INTO "books" VALUES(435,'Our Endless Numbered Days','Claire Fuller','1976: Peggy Hillcoat is eight. She spends her summer camping with her father, playing her beloved record of ''The Railway Children'' and listening to her mother''s grand piano, but her pretty life is about to change. Her survivalist father, who has been stockpiling provisions for the end which is surely coming soon, takes her from London to a cabin in a remote European forest. There he tells Peggy the rest of the world has disappeared. Her life is reduced to a piano which makes music but no sound, a forest where all that grows is a means of survival. And a tiny wooden hut that is everything. She is not seen again for another nine years.','Drama','','','','9780241003947','',1,0,'0',0,NULL,NULL);
INSERT INTO "books" VALUES(436,'The Shepherd''s Crown','Terry Pratchett','Terry Pratchett''s final Discworld novel, and the fifth to feature the witch Tiffany Aching. A SHIVERING OF WORLDS Deep in the Chalk, something is stirring. The owls and the foxes can sense it, and Tiffany Aching feels it in her boots. An old enemy is gathering strength. This is a time of endings and beginnings, old friends and new, a blurring of edges and a shifting of power. Now Tiffany stands between the light and the dark, the good and the bad. As the fairy horde prepares for invasion, Tiffany must summon all the witches to stand with her. To protect the land. Her land. There will be a reckoning. . . . THE FINAL DISCWORLD® NOVEL','Fantasy','','','','9780062429988','',1,0,'0',0,NULL,NULL);
INSERT INTO "books" VALUES(437,'Hậu vận rất đắt xin đừng lãng phí (VN language)','Mèo Maverick','Đa số đau khổ của con người đều bắt nguồn từ: dã tâm đúng lúc nhưng năng lực không theo kịp; dục vọng đúng lúc nhưng tiền không theo kịp; chờ mong đúng lúc nhưng tình cảm không theo kịp. Ở cái thời đại khắp nơi đều khoe khoang thu nhập, rất nhiều người có xu hướng vì tiền tài mà chẳng tiếc sức khỏe lao đầu vào công việc, họ chà đạp và hãm hại lẫn nhau, còn những người toàn tâm toàn ý cố gắng phấn đấu lại bị chê cười. Ai nấy đều ngưỡng mộ những người thành công, khát vọng mình sớm vừa nổi tiếng vừa giàu có. Không ai thèm để mắt đến những người bình thường, không ai thèm quan tâm đến những người bình thường, nhưng ở một góc của cuộc sống, rất nhiều người chúng ta tưởng là bình thường, lại đang dốc sức cố gắng theo cách của riêng họ. Khi chúng ta trốn tránh ánh nắng chói chang của ngày hè, lười biếng ngủ trưa trong phòng điều hoà, nghĩ cách bùng học, bùng làm trong những ngày đông mưa lạnh, thì họ - những con người tưởng như bình thường đến tầm thường kia, lại tự phác họa ra con đường đi cho chính mình.','Reference','','','','9786047787609','',1,0,'0',0,NULL,NULL);
